using System.IdentityModel.Tokens.Jwt;using System.Security.Claims;using System.Text;using Microsoft.EntityFrameworkCore;using Microsoft.IdentityModel.Tokens;using QuanLyKho.Data;using QuanLyKho.DTOs;namespace QuanLyKho.Services;public sealed class AuthService{readonly ApplicationDbContext db;readonly IConfiguration cfg;public AuthService(ApplicationDbContext db,IConfiguration cfg){this.db=db;this.cfg=cfg;}public async Task<LoginResponse> LoginAsync(LoginRequest r){var u=await db.Users.AsNoTracking().FirstOrDefaultAsync(x=>x.Username==r.Username.Trim());if(u is null||!BCrypt.Net.BCrypt.Verify(r.Password,u.Password))throw new UnauthorizedAccessException("Tài khoản hoặc mật khẩu không chính xác.");var exp=DateTime.UtcNow.Add(r.RememberMe?TimeSpan.FromDays(30):TimeSpan.FromHours(8));var claims=new[]{new Claim(ClaimTypes.NameIdentifier,u.Id.ToString()),new Claim(ClaimTypes.Name,u.Username),new Claim(ClaimTypes.GivenName,u.Fullname),new Claim(ClaimTypes.Role,u.Role)};var key=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(cfg["Jwt:Key"]!));var t=new JwtSecurityToken(cfg["Jwt:Issuer"],cfg["Jwt:Audience"],claims,expires:exp,signingCredentials:new SigningCredentials(key,SecurityAlgorithms.HmacSha256));return new(new JwtSecurityTokenHandler().WriteToken(t),exp,new(u.Id,u.Username,u.Fullname,u.Role));}public async Task<AuthUserDto> MeAsync(int id){var u=await db.Users.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id)??throw new KeyNotFoundException("Không tìm thấy người dùng.");return new(u.Id,u.Username,u.Fullname,u.Role);}}